const $=s=>document.querySelector(s),sleep=ms=>new Promise(resolve=>setTimeout(resolve,ms)),assert=(v,m)=>{if(!v)throw Error(m);};
const hash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(n=>n.toString(16).padStart(2,'0')).join('');
const files=['app.js','engine.js','censor.js','deck-scratch.js','deck-scratch-kernel.js','deck-scratch-worklet.js','deck-midi.js','keylock.js','keylock-scratch-shadow.js','censor-harness.js'];
const identities=async()=>Object.fromEntries(await Promise.all(files.map(async f=>[f,await hash(await(await fetch(f,{cache:'no-store'})).arrayBuffer())])));
async function until(fn,label,ms=20000){const end=performance.now()+ms;while(!fn()){assert(performance.now()<end,label+' timed out');await sleep(10);}}
const button=(n,a)=>`[data-deck="${n}"][data-action="${a}"]`,click=s=>{assert($(s),'Missing '+s);$(s).click();};
function key(k,up=false,target=document.body){target.dispatchEvent(new KeyboardEvent(up?'keyup':'keydown',{key:k.toUpperCase(),code:'Key'+k.toUpperCase(),shiftKey:!up,bubbles:true,cancelable:true}));}
function pointer(down){const target=down?$(button(0,'censor')):document.body;assert(target&&!target.disabled,'Censor control unavailable');target.dispatchEvent(new PointerEvent(down?'pointerdown':'pointerup',{pointerId:41,button:0,buttons:down?1:0,bubbles:true,cancelable:true}));}
function base64(bytes){let s='';for(let i=0;i<bytes.length;i+=16384)s+=String.fromCharCode(...bytes.subarray(i,i+16384));return btoa(s);}
function measure(data,sr,from,to){const start=Math.ceil(from*sr),end=Math.floor(to*sr),cross=[];let sum=0;assert(start>=0&&end<=data.length&&end>start,'Invalid fixed audio window');for(let n=start;n<end;n++){sum+=data[n]**2;if(n>start&&data[n-1]<0&&data[n]>=0)cross.push((n-1-data[n-1]/(data[n]-data[n-1]))/sr);}return{from,to,rms:Math.sqrt(sum/(end-start)),hz:cross.length>3?(cross.length-1)/(cross.at(-1)-cross[0]):null};}
let app;
async function run(){
 const {engine,state}=app,report={startedAt:new Date().toISOString(),completed:false,scope:'Actual normal browser pointer/U/J/MIDI Censor on raw chirp and fixed keylocked+2/tempo1.08. Synthetic inputs, not native/physical/reference/warped/selected-stem/full transport acceptance.',criteria:{cursorReturnSeconds:.010,frequencyErrorHz:1,playingMinimumRMS:.005,windowStart:.10,windowEnd:.35},events:[],checks:[],errors:[]};$('#censor-run').disabled=true;
 const event=(name,expectedLeft,slope=0)=>{const e={name,time:engine.ctx.currentTime-engine.recordStarted,expectedLeftAtEvent:expectedLeft,leftSlopeHzPerSecond:slope,expectedRight:550};report.events.push(e);return e;};
 const scratch=()=>engine.voices.get(0)?.deckScratchTransport;
 const factory=engine.createForwardKeylock;report.livePreparations=[];engine.createForwardKeylock=async function(options){report.livePreparations.push({time:this.ctx.currentTime-this.recordStarted,bufferMatchesCurrent:options.buffers[0]===this.buffers.get(state.decks[0].track.id),bufferSHA:await hash(options.buffers[0].getChannelData(0).buffer),rate:options.rate,semitones:options.semitones});return factory.call(this,options);};
 try{
  report.sourceBefore=await identities();await engine.resume();engine.audioMonitor.mutePhysical(true);await until(()=>!state.analysis,'Initial analysis');state.settings['Playback Keys Use Shift']=true;state.settings['Sync Mode']='Simple Sync';
  for(const d of state.decks)engine.pause(d);for(const bank of state.fx)for(const slot of bank)slot.on=false;engine.configureFX(state.fx,state.fxRoutes||[],state.decks.map(d=>(d.track?.bpm||120)*d.rate),state.fxTempo);
  function fixture(chirp){for(let n=0;n<2;n++){const d=state.decks[n],b=engine.ctx.createBuffer(2,48000*18,48000),data=b.getChannelData(n);for(let i=0;i<data.length;i++){const t=i/48000;data[i]=.12*Math.sin(2*Math.PI*(n?550*t:chirp?300*t+20*t*t:330*t));}Object.assign(d.track,{duration:18,bpm:120,grid:0,gridWarpMarkers:[],analyzed:true});Object.assign(d,{position:5,rate:1,keylock:false,keyShift:0,reverse:false,loop:false,slip:false,stemSlip:'off',sync:false,mode:'INT',level:.8});engine.clearDeckScratchCache(n);engine.buffers.set(d.track.id,b);engine.mix(n,'level',.8);}}
  fixture(true);click(button(0,'quantize'));assert($(button(0,'censor')).disabled,'Paused Censor should not audition');for(let n=0;n<2;n++){click(button(n,'play'));await until(()=>state.decks[n].playing&&!state.decks[n].processing,'Raw deck Play');}
  const d=state.decks[0],clock=engine.voiceClock(d,engine.voices.get(0));await engine.recordStart();event('raw-before',300+40*clock(engine.ctx.currentTime),40);await sleep(450);
  pointer(true);await until(()=>engine.deckScratchRequests.get(0)?.ready&&scratch()?.state().phase==='censor','Pointer Censor');key('u');key('j');await until(()=>engine.voices.get(1)?.deckScratchTransport?.state().phase==='censor','Right J Censor');
  const markReverse=name=>{const s=scratch().state(),pos=s.audiblePosition+(engine.ctx.currentTime-s.audioTime)*s.velocity;return event(name,300+40*pos,-40);};
  report.rawStart=scratch().state();markReverse('raw-reverse-early');await sleep(550);markReverse('raw-reverse-late');await sleep(450);report.rawHeld=scratch().state();assert(report.rawHeld.audiblePosition<report.rawStart.audiblePosition-.8,'Censor did not continuously reverse');assert(report.rawHeld.hidden.position>report.rawStart.hidden.position+.8,'Forward clock did not advance');assert(!d.slip&&!d.reverse,'Censor changed persistent Slip/Reverse');
  pointer(false);await sleep(40);assert(scratch().state().phase==='censor','Pointer release ended another held keyboard input');key('u',true,$('#search'));key('j',true,$('#search'));await until(()=>!engine.deckScratchRequests.has(0)&&!engine.deckScratchRequests.has(1),'Release both keyboard holds');
  report.rawReturn={actual:engine.position(d),expected:clock(engine.ctx.currentTime)};assert(Math.abs(report.rawReturn.actual-report.rawReturn.expected)<.010,'Raw return missed forward clock');event('raw-return',300+40*clock(engine.ctx.currentTime),40);await sleep(450);report.checks.push('Raw pointer/U/J continuous reverse, independent forward clock, shared holds and input-targeted release');
  for(let n=0;n<2;n++){click(button(n,'play'));await until(()=>!state.decks[n].playing,'Stop raw stage');}fixture(false);click(button(0,'quantize'));click(button(0,'keyUp'));click(button(0,'keyUp'));await until(()=>d.keylock&&d.keyShift===2,'Set key+2');
  const tempo=$('[data-tempo="0"]');tempo.value='8';tempo.dispatchEvent(new Event('input',{bubbles:true}));await until(()=>Math.abs(d.rate-1.08)<1e-9,'Tempo+8%');for(let n=0;n<2;n++){click(button(n,'play'));await until(()=>state.decks[n].playing&&!state.decks[n].processing,'Pitched deck Play');}
  await until(()=>engine.ctx.currentTime>=d.anchorTime+.05,'Keylocked scheduled audio start');
  report.pitchedSource={time:engine.ctx.currentTime-engine.recordStarted,anchor:d.anchorTime-engine.recordStarted,sourceMatchesCurrent:engine.voices.get(0)?.liveKeylock?.sources[0].buffer===engine.buffers.get(d.track.id),currentSHA:await hash(engine.buffers.get(d.track.id).getChannelData(0).buffer)};
  const pitchedClock=engine.voiceClock(d,engine.voices.get(0)),expected=330*2**(2/12);event('pitched-before',expected);await sleep(450);
  click('[data-panel="midi"]');const field=(s,v)=>{$(s).value=String(v);};field('#midi-target','Deck 1 censor');field('#midi-type','Note');field('#midi-channel',1);field('#midi-number',13);field('#midi-encoding','7-bit absolute');click('#midi-add');
  const send=value=>{field('#midi-type','Note');field('#midi-channel',1);field('#midi-number',13);field('#midi-test-value',value);click('#midi-send');};send(127);click('#modal-close');await until(()=>engine.deckScratchRequests.get(0)?.ready&&scratch()?.state().phase==='censor','Pitched MIDI Censor',30000);
  report.pitchedStart=scratch().state();key('u');event('pitched-reverse',expected);await sleep(950);click('[data-panel="midi"]');send(0);click('#modal-close');assert(scratch().state().phase==='censor','MIDI release ended held keyboard Censor');window.dispatchEvent(new Event('blur'));await until(()=>!engine.deckScratchRequests.has(0)&&!d.censor,'Blur releases final Censor',30000);
  report.pitchedReturn={actual:engine.position(d),expected:pitchedClock(engine.ctx.currentTime),live:!!engine.voices.get(0)?.liveKeylock};assert(Math.abs(report.pitchedReturn.actual-report.pitchedReturn.expected)<.010,'Pitched return missed forward clock');event('pitched-return',expected);await sleep(450);report.checks.push('Actual MIDI and keyboard shared pitched Censor; Note Off and blur; fixed-key/tempo forward-clock return');
  for(let n=0;n<2;n++){click(button(n,'play'));await until(()=>!state.decks[n].playing,'Final Pause');}const mode=$('[data-mode="0"]');mode.value='ABS';mode.dispatchEvent(new Event('change',{bubbles:true}));assert($(button(0,'censor')).disabled,'ABS Censor is enabled');key('u');await sleep(20);assert(!d.censor&&!engine.deckScratchRequests.has(0),'ABS/paused Censor activated');report.checks.push('Paused and Absolute-mode UI do not start Censor');
 }catch(error){report.errors.push({message:error.message,stack:error.stack});}
 finally{
  engine.createForwardKeylock=factory;
  pointer(false);key('u',true);key('j',true);window.dispatchEvent(new Event('blur'));for(const d of state.decks)engine.pause(d);
  if(engine.recording){const blob=await engine.recordStop();if(blob){const bytes=new Uint8Array(await blob.arrayBuffer());report.recording={bytes:bytes.length,format:blob.type,sha256:await hash(bytes),base64:base64(bytes)};try{const decoded=await engine.ctx.decodeAudioData(bytes.buffer.slice(0));report.decoded={duration:decoded.duration,sampleRate:decoded.sampleRate,frames:decoded.length,channels:decoded.numberOfChannels};assert(decoded.numberOfChannels===2,'Expected stereo');for(let c=0;c<2;c++)for(const v of decoded.getChannelData(c))assert(Number.isFinite(v),'Nonfinite whole recording');
   report.audio=report.events.map(e=>({name:e.name,expectedLeft:e.expectedLeftAtEvent+e.leftSlopeHzPerSecond*.225,expectedRight:e.expectedRight,channels:[0,1].map(c=>measure(decoded.getChannelData(c),decoded.sampleRate,e.time+.10,e.time+.35))}));for(const w of report.audio)for(let c=0;c<2;c++){const m=w.channels[c],hz=c?w.expectedRight:w.expectedLeft;assert(m.rms>.005&&Math.abs(m.hz-hz)<1,`${w.name} channel ${c} failed pitch/audio gate (${m.hz} vs ${hz})`);}assert(report.audio.length===7,'Missing seven declared windows');report.checks.push('Seven fixed whole-master chirp/tone windows; forward and reverse key processing');
  }catch(error){report.errors.push({message:error.message,stack:error.stack});}}}
  report.sourceAfter=await identities();report.sourceStable=JSON.stringify(report.sourceBefore)===JSON.stringify(report.sourceAfter);report.completed=report.checks.length===4&&!report.errors.length&&report.sourceStable;report.finishedAt=new Date().toISOString();$('#censor-original').textContent=JSON.stringify(report,null,2);$('#censor-results').textContent=JSON.stringify({...report,recording:report.recording?{...report.recording,base64:'Retained in complete original'}:null},null,2);$('#censor-status').textContent=report.completed?'Scoped Censor workflow passed; audio stopped':'Failed: '+report.errors.map(e=>e.message).join('; ');const link=$('#censor-download');link.href=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json'}));link.download='censor-original.json';link.hidden=false;
 }
}
$('#censor-run').onclick=()=>run();
async function boot(){const parsed=new DOMParser().parseFromString(await(await fetch('index.html')).text(),'text/html');for(const n of [...parsed.body.children])if(n.tagName!=='SCRIPT')document.body.append(n);await import('./app.js');await until(()=>window.openPlay?.state.decks[1].track,'Actual app');app=window.openPlay;$('#censor-run').disabled=false;$('#censor-run').textContent='Run one Censor workflow';}
boot().catch(error=>$('#censor-status').textContent=error.message);
